'use strict';
// View windows never replace execution IDs, configuration snapshots, or exported content.
const wnBase={handleAction,render,previewParsedMarkup,previewEnsure,previewRelease,closeModal};
const wnMaterialViews=new Map(),wnReaders=new Map(),wnRawPositions=new Map();
const WN_FILE_PAGE=50,WN_TEXT_CHUNK=6000;
function wnAllDocs(){return state.toolId==='extract'?ewDocs():twDocs();}
function wnMaterialView(){const key=state.toolId+':'+(currentTask()?.id||'draft');if(!wnMaterialViews.has(key)){if(wnMaterialViews.size>=30)wnMaterialViews.delete(wnMaterialViews.keys().next().value);wnMaterialViews.set(key,{page:1,query:'',total:0,scroll:0});}return wnMaterialViews.get(key);}
function wnWindow(docs,query){const v=wnMaterialView();if(v.query!==query){v.page=1;v.query=query;v.scroll=0;}v.total=docs.length;v.page=Math.max(1,Math.min(v.page,Math.ceil(docs.length/WN_FILE_PAGE)||1));return docs.slice((v.page-1)*WN_FILE_PAGE,v.page*WN_FILE_PAGE);}
function wnMaterialPager(){const v=wnMaterialView(),all=wnAllDocs().length,pages=Math.max(1,Math.ceil(v.total/WN_FILE_PAGE));if(all<=WN_FILE_PAGE&&!v.query)return '';return '<nav class="wn-material-pager" aria-label="已选资料清单翻页" title="每页最多50份，仅切换左侧已选资料的显示"><div>'+B('上一页','wn-files-prev','sm','aria-label="资料上一页" '+(v.page<=1?'disabled':''))+'<label>第 <input type="number" min="1" max="'+pages+'" value="'+v.page+'" data-wn-change="files-page" aria-label="资料页码"> / '+pages+' 页</label>'+B('下一页','wn-files-next','sm','aria-label="资料下一页" '+(v.page>=pages?'disabled':''))+B('定位当前','wn-locate','ghost sm','title="清除查找并定位当前预览文件，不改变已选资料" '+(!ws().preview?'disabled':''))+'</div></nav>';}
function wnGoFiles(n){const v=wnMaterialView();v.page=Math.max(1,Math.min(n,Math.ceil(v.total/WN_FILE_PAGE)||1));v.scroll=0;render();}
function wnLocate(){const d=file(ws().preview),v=wnMaterialView(),docs=wnAllDocs(),i=docs.findIndex(x=>x.id===d?.id);if(i<0)return;if(state.toolId==='extract')ws().treeQuery='';else tv().query='';v.query='';v.page=Math.floor(i/WN_FILE_PAGE)+1;v.scroll=0;const ancestors=folderPath(d.folder).split('/').filter(Boolean).map((_,i,a)=>d.space+'::'+a.slice(0,i+1).join('/'));ewView.closed=ewView.closed.filter(k=>!ancestors.includes(k));if(state.toolId!=='extract')tv().closed=tv().closed.filter(k=>!ancestors.includes(k));render();const tree=$('.ew-materials .ew-tree,.tw-tree'),row=tree?.querySelector('.ew-file.active,.tw-file.active');if(tree&&row){tree.scrollTop=Math.max(0,row.offsetTop-tree.offsetTop-tree.clientHeight/2);v.scroll=tree.scrollTop;}}
// Only a bounded number of document reading sessions are retained, in memory for this visit.
function wnReader(d){let v=wnReaders.get(d.id),text=previewText(d);if(!v||v.text!==text){v={id:d.id,text,starts:[0],page:0,query:'',draft:'',hits:[],hit:0,scroll:0};if(text.length>12000){let start=0;while(start+WN_TEXT_CHUNK<text.length){let end=start+WN_TEXT_CHUNK,br=text.lastIndexOf('\n',end);if(br>start+WN_TEXT_CHUNK*.6)end=br+1;if(/[\uD800-\uDBFF]/.test(text[end-1]))end--;v.starts.push(end);start=end;}}wnReaders.set(d.id,v);}else{wnReaders.delete(d.id);wnReaders.set(d.id,v);}while(wnReaders.size>12)wnReaders.delete(wnReaders.keys().next().value);return v;}
function wnReadingText(v){const start=v.starts[v.page],end=v.starts[v.page+1]??v.text.length,part=v.text.slice(start,end);if(!v.query)return v.starts.length===1?previewMarkdown(part):'<pre class="wn-text">'+E(part)+'</pre>';const ranges=v.hits.map((p,i)=>({p,i})).filter(x=>x.p<end&&x.p+v.query.length>start);let cursor=start,out='';for(const {p,i} of ranges){const a=Math.max(start,p),b=Math.min(end,p+v.query.length);out+=E(v.text.slice(cursor,a))+'<mark '+(i===v.hit?'data-current="true"':'')+'>'+E(v.text.slice(a,b))+'</mark>';cursor=b;}return '<pre class="wn-text">'+out+E(v.text.slice(cursor,end))+'</pre>';}
function wnReaderMarkup(v){return '<section class="wn-reader" data-wn-reader="'+E(v.id)+'" aria-label="解析正文阅读"><form class="wn-find" data-wn-find="'+E(v.id)+'"><input aria-label="查找全文" placeholder="查找全文，回车定位" maxlength="100" value="'+E(v.draft)+'"><button class="btn sm" type="submit">查找</button>'+B(I('close','icon-sm'),'wn-text-clear','ghost sm','aria-label="清除正文查找" title="清除正文查找"')+'</form>'+(v.query?'<div class="wn-hits" role="status"><span>'+(v.hits.length?'匹配 <strong>'+(v.hit+1)+'</strong> / '+v.hits.length+' 处':'全文未找到“'+E(v.query)+'”')+'</span>'+B(I('back','icon-sm'),'wn-hit-prev','ghost sm','aria-label="上一个匹配" '+(v.hit<=0||!v.hits.length?'disabled':''))+B(I('chevron','icon-sm'),'wn-hit-next','ghost sm','aria-label="下一个匹配" '+(v.hit>=v.hits.length-1?'disabled':''))+'</div>':'')+'<article class="preview-parsed-markdown wn-reader-body" tabindex="0" aria-label="解析正文">'+wnReadingText(v)+'</article>'+(v.starts.length>1?'<nav class="wn-text-pager" aria-label="长正文分段"><label>阅读段 <input type="number" min="1" max="'+v.starts.length+'" value="'+(v.page+1)+'" data-wn-change="text-page" aria-label="正文阅读段"> / '+v.starts.length+'</label><div>'+B(I('back','icon-sm'),'wn-text-prev','sm','aria-label="上一阅读段" '+(v.page===0?'disabled':''))+B(I('chevron','icon-sm'),'wn-text-next','sm','aria-label="下一阅读段" '+(v.page===v.starts.length-1?'disabled':''))+'</div><span title="仅分段展示正文，不是原文件页码，也不改变 AI 分析或导出范围。">全文参与分析 · 分段仅便于阅读</span></nav>':'')+'</section>';}
previewParsedMarkup=function(d){if(d&&!auditFileAccess(d).preview)return previewMessage('无预览权限','请联系资料管理员。');if(!d||!libReady(d)||!previewText(d))return wnBase.previewParsedMarkup(d);return wnReaderMarkup(wnReader(d));};
function wnReaderElement(id){return [...document.querySelectorAll('[data-wn-reader]')].find(n=>n.dataset.wnReader===id&&n.getClientRects().length)||[...document.querySelectorAll('[data-wn-reader]')].find(n=>n.dataset.wnReader===id);}
function wnPaintReader(v,focusHit=false){const old=wnReaderElement(v.id),focused=old?.contains(document.activeElement)?document.activeElement:null,action=focused?.dataset.action,wasSearch=focused?.matches('.wn-find input,.wn-find button[type=submit]');if(!old||!auditFileAccess(file(v.id)).preview)return;old.outerHTML=wnReaderMarkup(v);const next=wnReaderElement(v.id),body=next?.querySelector('.wn-reader-body');if(body){body.scrollTop=v.scroll;if(focusHit){const hit=body.querySelector('[data-current]');if(hit)body.scrollTop=Math.max(0,hit.getBoundingClientRect().top-body.getBoundingClientRect().top+body.scrollTop-body.clientHeight/3);v.scroll=body.scrollTop;}}if(wasSearch)next?.querySelector('.wn-find input')?.focus({preventScroll:true});else if(action)next?.querySelector('[data-action="'+action+'"]')?.focus({preventScroll:true});}
function wnFind(v,query){v.query=query.trim();v.draft=query;v.hits=[];v.hit=0;v.scroll=0;if(v.query){const escaped=v.query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');for(const match of v.text.matchAll(new RegExp(escaped,'giu')))v.hits.push(match.index);if(v.hits.length)v.page=wnTextPage(v,v.hits[0]);}wnPaintReader(v,true);}
function wnTextPage(v,offset){let low=0,high=v.starts.length-1;while(low<high){const mid=Math.ceil((low+high)/2);if(v.starts[mid]<=offset)low=mid;else high=mid-1;}return low;}
function wnRememberRaw(){const s=activeFilePreview;if(!s)return;const p=s.data;wnRawPositions.delete(s.id);wnRawPositions.set(s.id,{rawPage:p.rawPage||1,rawZoom:p.rawZoom||'fit',rawSheet:p.rawSheet,rawTablePage:p.rawTablePage||1});while(wnRawPositions.size>40)wnRawPositions.delete(wnRawPositions.keys().next().value);}
previewRelease=function(){wnRememberRaw();return wnBase.previewRelease();};
previewEnsure=function(p){if(activeFilePreview?.data!==p&&wnRawPositions.has(p.id))Object.assign(p,wnRawPositions.get(p.id));return wnBase.previewEnsure(p);};
// Task source navigation keeps per-file AI status separate from document parsing status.
const wnTaskViews=new Map();
function wnTaskView(t){if(!wnTaskViews.has(t.id)){if(wnTaskViews.size>=30)wnTaskViews.delete(wnTaskViews.keys().next().value);wnTaskViews.set(t.id,{query:'',status:'all',page:1});}return wnTaskViews.get(t.id);}
function wnSourceStatus(t,id){return t.successIds?.includes(id)?'success':t.failedIds?.includes(id)?'failed':t.status==='stopped'?'stopped':'pending';}
const wnSourceLabels={success:'分析成功',failed:'分析失败',stopped:'未处理',pending:'尚未返回结果'};
function wnTaskSources(t){const c=tcCount(t),v=wnTaskView(t),index=new Map(state.docs.map(d=>[d.id,d])),ids=(t.ids||[]).filter(id=>{const d=index.get(id),visible=d&&!d.deleted&&auditFileAccess(d).read;return(v.status==='all'||wnSourceStatus(t,id)===v.status)&&(!v.query||visible&&(d.name+' '+ewPath(d)).toLowerCase().includes(v.query.toLowerCase()));}),pages=Math.max(1,Math.ceil(ids.length/WN_FILE_PAGE));v.page=Math.max(1,Math.min(v.page,pages));return modalFrame('任务信息',E(t.name),'<div class="tc-info-status">'+tag(...tcLabel(t))+'<span>共 <strong>'+c.total+'</strong> 份 · 分析成功 <strong>'+c.ok+'</strong> · 分析失败 <strong>'+c.fail+'</strong>'+(c.pending?' · '+(t.status==='stopped'?'未处理':'尚未返回')+' <strong>'+c.pending+'</strong>':'')+'</span></div><div class="tc-info-tabs">'+[['overview','进度与结果'],['sources','分析资料 ('+c.total+')'],['config','执行配置']].map(([k,n])=>B(n,'tc-info-tab',k==='sources'?'soft sm':'ghost sm','data-tab="'+k+'"')).join('')+'</div><form class="wn-task-search" data-wn-task-search><input aria-label="查找任务资料" placeholder="查找文件名称或目录" value="'+E(v.query)+'"><select aria-label="工具分析状态" data-wn-change="task-status"><option value="all">全部分析状态</option>'+Object.entries(wnSourceLabels).map(([key,name])=>'<option value="'+key+'" '+(v.status===key?'selected':'')+'>'+name+'</option>').join('')+'</select><button type="submit" class="btn sm">查询</button></form><p class="hint">这里显示工具分析状态；“分析成功”不代表审计结论已确认。</p><div class="wn-task-source-table">'+simpleTable(['文件名称','资料位置','工具分析状态','原文'],ids.slice((v.page-1)*WN_FILE_PAGE,v.page*WN_FILE_PAGE).map(id=>{const d=index.get(id),visible=d&&!d.deleted&&auditFileAccess(d).read,s=wnSourceStatus(t,id);return [visible?E(d.name):'原资料已移除或无查看权限',visible?E(ewPath(d)):'—',tag(wnSourceLabels[s],s==='failed'?'red':s==='success'?'green':''),visible&&auditFileAccess(d).preview?A('查看原文','source','data-id="'+E(id)+'"'):'当前不可查看'];}),true)+(!ids.length?'<p class="wn-empty">没有符合条件的资料，请调整查找条件。</p>':'')+'</div>','<div class="wn-task-pager"><span>匹配 <strong>'+ids.length+'</strong> 份 · '+v.page+' / '+pages+' 页</span>'+B('上页','wn-task-prev','sm',v.page<=1?'disabled':'')+B('下页','wn-task-next','sm',v.page>=pages?'disabled':'')+'</div>'+B('关闭','close-modal'),'tc-info-dialog wn-task-dialog');}
let wnSourceReturn=null;
closeModal=function(){if(modal==='source'&&wnSourceReturn){const back=wnSourceReturn;wnSourceReturn=null;wnBase.closeModal();if(state.tasks.some(t=>t.id===back.id)){tcView.infoTab='sources';openModal('tc-info',back);}return;}return wnBase.closeModal();};
handleAction=function(action,el){
 if(action==='source'&&modal==='tc-info'&&tcView.infoTab==='sources')wnSourceReturn={id:modalData.id};
 if(action==='wn-files-prev'||action==='wn-files-next')return wnGoFiles(wnMaterialView().page+(action==='wn-files-next'?1:-1));
 if(action==='wn-locate')return wnLocate();
 if(action.startsWith('wn-text-')||action.startsWith('wn-hit-')){const node=el.closest?.('[data-wn-reader]'),v=wnReaders.get(node?.dataset.wnReader);if(!v||!auditFileAccess(file(v.id)).preview)return;if(action==='wn-text-clear')return wnFind(v,'');if(action.startsWith('wn-hit-')){v.hit=Math.max(0,Math.min(v.hits.length-1,v.hit+(action==='wn-hit-next'?1:-1)));if(v.hits.length)v.page=wnTextPage(v,v.hits[v.hit]);}else v.page=Math.max(0,Math.min(v.starts.length-1,v.page+(action==='wn-text-next'?1:-1)));v.scroll=0;return wnPaintReader(v,action.startsWith('wn-hit-'));}
 if((action==='wn-task-prev'||action==='wn-task-next')&&modal==='tc-info'){const t=state.tasks.find(t=>t.id===modalData.id);if(t){wnTaskView(t).page+=action==='wn-task-next'?1:-1;paintModal();}return;}
 return wnBase.handleAction(action,el);
};
window.addEventListener('submit',e=>{if(e.target.matches('[data-wn-find]')){e.preventDefault();e.stopImmediatePropagation();const v=wnReaders.get(e.target.dataset.wnFind);if(v&&auditFileAccess(file(v.id)).preview)wnFind(v,e.target.querySelector('input').value);}else if(e.target.matches('[data-wn-task-search]')&&modal==='tc-info'){e.preventDefault();e.stopImmediatePropagation();const t=state.tasks.find(t=>t.id===modalData.id);if(t){Object.assign(wnTaskView(t),{query:e.target.querySelector('input').value.trim(),page:1});paintModal();}}},true);
window.addEventListener('change',e=>{const kind=e.target.dataset.wnChange;if(!kind)return;e.stopImmediatePropagation();const n=Number(e.target.value);if(kind==='files-page'){if(Number.isInteger(n)&&n>0)wnGoFiles(n);else e.target.value=wnMaterialView().page;}if(kind==='text-page'){const v=wnReaders.get(e.target.closest('[data-wn-reader]').dataset.wnReader);if(v&&Number.isInteger(n)&&n>0){v.page=Math.min(n-1,v.starts.length-1);v.scroll=0;wnPaintReader(v);}else if(v)e.target.value=v.page+1;}if(kind==='task-status'&&modal==='tc-info'){const t=state.tasks.find(t=>t.id===modalData.id);if(t){const v=wnTaskView(t);v.query=$('[data-wn-task-search] input')?.value.trim()||'';v.status=e.target.value;v.page=1;paintModal();}}},true);
window.addEventListener('input',e=>{const form=e.target.closest?.('[data-wn-find]');if(form){const v=wnReaders.get(form.dataset.wnFind);if(v)v.draft=e.target.value;}},true);
window.addEventListener('scroll',e=>{if(e.target.matches?.('.wn-reader-body')){const v=wnReaders.get(e.target.closest('[data-wn-reader]').dataset.wnReader);if(v)v.scroll=e.target.scrollTop;}if(e.target.matches?.('.ew-materials .ew-tree,.tw-tree'))wnMaterialView().scroll=e.target.scrollTop;},true);
render=function(){wnBase.render();if(state.view==='tool'){const tree=$('.ew-materials .ew-tree,.tw-tree');if(tree){const v=wnMaterialView();tree.scrollTop=v.scroll;const note=$('.ew-materials .ew-scope-note'),from=(v.page-1)*WN_FILE_PAGE+1,to=Math.min(v.page*WN_FILE_PAGE,v.total),range=from===to?'本页第 '+to+' 份':'本页第 '+from+'–'+to+' 份';if(note&&(state.toolId==='extract'||!['bidding','association'].includes(state.toolId))){note.innerHTML=(currentTask()?'本次资料 <strong>'+wnAllDocs().length+'</strong> 份':'已选 <strong>'+wnAllDocs().length+'</strong> 份资料')+(v.query?' · 匹配 <strong>'+v.total+'</strong> 份':'')+(v.total>WN_FILE_PAGE?' · <span class="wn-file-range">'+range+'</span>':'');note.title='清单每页最多显示50份，翻页不改变已选资料';} }}document.querySelectorAll('[data-wn-reader]').forEach(n=>{const v=wnReaders.get(n.dataset.wnReader),body=n.querySelector('.wn-reader-body');if(v&&body)body.scrollTop=v.scroll;});};
render();
